import { knowledgePage, knowledgeDelete, knowledgeTree, knowledgeUploadFile } from "@/api/ictOperation/index"
// 文件上传
import website from '@/config/website';
import {Base64} from 'js-base64';
import {getToken} from '@/util/auth'
import { formatDate } from '@/util/date'
import operateForm from './operateForm'

export default {
  props: ['isShow'],
  components: { operateForm },
  data() {
    return{
      showOperate: false,
      questionId: undefined,

      searchForm: {
        current: 1,
        size: 20,
        resourceCondition: '',
        type: undefined
      },
      tableData: [],
      total: 0,
      tableLoading: false,
      action: '#', // /api/idevelop-control/knowledge/load
      headers: {
        Authorization: `Basic ${Base64.encode(`${website.clientId}:${website.clientSecret}`)}`,
        'Idevelop-Auth': 'bearer ' + getToken()
      },

      treeData: [],

    }
  },
  mounted() {
    this.getList()
    knowledgeTree({}).then(res => {
      this.treeData = res.data
    })
  },
  methods: {
    uploadFile2( params ){
      const file = params.file

      const formData = new FormData()
      formData.append("file", file)

      knowledgeUploadFile(formData).then(res=>{
        params.onSuccess(res)
      })
    },
    // 导出
    handleExport() {
      this.download(
        "/api/idevelop-control/knowledge/export",
        this.searchForm,
        "知识库.xlsx"
      );
    },
    handleNodeClick(data){
      this.searchForm.type = data.key
      this.getList()
    },

    handle1(item){
      this.questionId = item.id
      this.showOperate = true
    },
    submitProcess(){
        this.showOperate = false
        this.getList()
    },

    showDictLable(status){
      switch (status) {
        case '0':
          return '暂存'
          // break;
        case '1':
          return '已提交'
          // break;
        case '2':
          return '已完成'
          // break;
        // default:
        //   break;
      }
    },
    getList() {
      this.tableLoading = true
      knowledgePage(this.searchForm).then(res => {
        this.tableData = res.data.records
        this.total = res.data.total
        this.tableLoading = false
      })
    },
    beforeUpload(file) {

    },
    handleFileSuccess(res, file, fileList) {
      if(res.code == 200) {
        this.$message({
          message: '问答上传成功！',
          type: 'success'
        });
        this.getList()
      }else {
        this.$message({
          message: res.msg,
          type: 'error'
        });
      }

    },
    search() {
      this.searchForm.current = 1
      this.getList()
    },
    restForm() {
      this.searchForm = {
        current: 1,
        size: 20,
        resourceCondition: '',
        type: undefined
      }
      this.getList()
      knowledgeTree({}).then(res => {
        this.treeData = res.data
      })
    },
    delBtn(row) {
      this.$confirm('确定删除该问答项?', '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(() => {
        knowledgeDelete({id: row.id}).then(res => {
          this.$message({
            message: '删除成功！',
            type: 'success'
          });
          this.getList()
        })
      })
    },

    handleDownload() {
      this.download('/api/idevelop-control/knowledge/download/template', {
        ...this.queryParams
      }, `智能问答上传模板${formatDate(new Date(), 'yyyy-MM-dd hh:mm:ss')}.xlsx`, '')
    }
  },
}
